ALTER TABLE public.ad_connections DROP CONSTRAINT ad_connections_status_check, ADD CONSTRAINT ad_connections_status_check CHECK(status IN('connected','expired','error','limited'));
ALTER TABLE public.campaign_snapshots DROP CONSTRAINT campaign_snapshots_level_check, ADD CONSTRAINT campaign_snapshots_level_check CHECK(level IN('campaign','group','ad_group','ad_set','ad','asset_group','keyword','search_term','placement'));
ALTER TABLE public.ads_api_versions ADD COLUMN sunset_month text, ADD COLUMN sunset_precision text NOT NULL DEFAULT 'unknown' CHECK(sunset_precision IN('exact','tentative_month','unknown'));
INSERT INTO public.ads_api_versions(platform,version,released_at,sunset_month,sunset_precision,source_url,verified_at,notes) VALUES('google','v26','2026-10-14','2027-11','tentative_month','https://developers.google.com/google-ads/api/docs/sunset-dates',now(),'November 2027 is tentative; no exact sunset day is published.'),('meta','v26.0','2026-07-29',NULL,'unknown','https://developers.facebook.com/blog/post/2026/07/29/introducing-graph-api-v26-and-marketing-api-v26/',now(),'Release verified. Marketing lifecycle table has no v26.0 sunset; do not use the Graph lifecycle as a substitute.');